/* ================= spaced review store ================= */
const RK="ml_review",INT=[0,1,3,7];
let RV=J(RK,{});
const rvSave=()=>{SV(RK,RV);badge()};
const due=()=>Object.entries(RV).filter(([k,v])=>v.due<=DAY());
function rvAdd(key,item,box){const ex=RV[key];if(ex){ex.box=Math.min(ex.box,box||0);ex.due=DAY(INT[ex.box]);ex.miss=(ex.miss||0)+1}else{const keys=Object.keys(RV);if(keys.length>400){keys.sort((a,b)=>RV[a].added<RV[b].added?-1:1).slice(0,keys.length-400).forEach(k=>delete RV[k])}RV[key]={...item,box:box||0,due:DAY(INT[box||0]),added:Date.now(),miss:1}}rvSave()}
function rvRight(key){const v=RV[key];if(!v)return;v.box++;if(v.box>=INT.length){delete RV[key];rvSave();return "mastered"}v.due=DAY(INT[v.box]);rvSave();return "in "+INT[v.box]+" day"+(INT[v.box]==1?"":"s")}
function rvWrong(key){const v=RV[key];if(!v)return;v.box=0;v.due=DAY(1);v.miss=(v.miss||0)+1;rvSave()}
function badge(){const n=due().length;$$(".ix-rvn").forEach(b=>{b.textContent=n;b.hidden=!n});const t=$("#ix-rvtop");if(t)t.title=n?`Today's review: ${n} item${n==1?"":"s"} due`:"Today's review: nothing due"}
/* ================= daily goal ================= */
let DG=J("ml_daily",{d:DAY(),n:0});if(DG.d!=DAY())DG={d:DAY(),n:0};
const goal=()=>J("ml_goal",3);
function bump(){if(DG.d!=DAY())DG={d:DAY(),n:0};DG.n++;SV("ml_daily",DG);ring();if(DG.n==goal())setTimeout(()=>toast("🎯 Daily goal reached. Well done!"),1900)}
function ringSVG(sz){const g=goal(),n=Math.min(DG.n,g),r=sz/2-3,c=2*Math.PI*r;return `<svg width="${sz}" height="${sz}" viewBox="0 0 ${sz} ${sz}" aria-hidden="true"><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="var(--line)" stroke-width="4"/><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="#157a3c" stroke-width="4" stroke-linecap="round" stroke-dasharray="${c*n/g} ${c}" transform="rotate(-90 ${sz/2} ${sz/2})"/></svg>`}
function ring(){const b=$("#ix-goal");if(!b)return;const g=goal();b.innerHTML=ringSVG(30)+`<span>${Math.min(DG.n,99)}/${g}</span>`;b.setAttribute("aria-label",`Daily goal: ${DG.n} of ${g} steps today`);b.title=`Daily goal: ${DG.n} of ${g} steps, cases or games finished today`;const s=$("#ix-goalbox");if(s)s.innerHTML=goalBox()}
function goalBox(){const g=goal();return `<div class="ix-goalrow">${ringSVG(56)}<div><b>${DG.n} of ${g}</b> finished today (steps, cases, games and review rounds).<div class="ctrl">Daily goal: ${[1,2,3,4,5].map(i=>`<button data-ixgoal="${i}" class="${i==g?"on":""}" aria-pressed="${i==g}">${i}</button>`).join("")}</div></div></div>`}
/* ================= gentler confetti ================= */
confetti=function(){if(matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches)return;const c=$("#confetti"),x=c.getContext("2d");c.width=innerWidth;c.height=innerHeight;
const cols=["#2f6fdb","#157a3c","#d9a400","#7b3fc4"];const P=[...Array(36)].map(()=>({x:innerWidth/2+(Math.random()-.5)*120,y:innerHeight*.45,vx:(Math.random()-.5)*6,vy:-Math.random()*6-2,c:cols[Math.floor(Math.random()*4)],s:3+Math.random()*3}));let f=0;
(function a(){x.clearRect(0,0,c.width,c.height);x.globalAlpha=Math.max(0,1-f/50);P.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.25;x.fillStyle=p.c;x.fillRect(p.x,p.y,p.s,p.s)});if(++f<50)requestAnimationFrame(a);else{x.globalAlpha=1;x.clearRect(0,0,c.width,c.height)}})()};
const _cp=complete;complete=function(id){const was=!!S.done[id];_cp.apply(this,arguments);if(!was&&S.done[id])bump()};
/* ================= quizzes: why the chosen option is wrong ================= */
let GL=null;const glByLabel=t=>{if(!GL){GL={};for(const k in GLOSSARY){const l=GLOSSARY[k].l.toLowerCase();if(!GL[l])GL[l]=GLOSSARY[k]}}return GL[PT(t).toLowerCase().replace(/[.\s]+$/,"")]};
function whyWrong(q,j){const opt=PT(q.o[j]);if(q.w&&q.w[j])return `Why not “${E(opt)}”: ${q.w[j]}`;const g=glByLabel(q.o[j]);
if(g)return `You picked “${E(opt)}”, which does not fit this question. A reminder of what it is: ${g.d}`;
return `You picked “${E(opt)}”, which does not fit this question. Check it against the key clue in the question.`}
bindQuiz=function(root,id,qs,onAll){root.querySelectorAll(".opt").forEach(b=>b.onclick=()=>{const i=b.dataset.q.split(/-(?=\d+$)/)[1];const q=qs[+i],j=+b.dataset.j;
const grp=root.querySelectorAll(`[data-q="${b.dataset.q}"]`);const fb=root.querySelector(`#fb-${b.dataset.q}`);const key="q:"+CUR+":"+b.dataset.q;
if(j===q.a){grp.forEach(x=>x.disabled=true);b.classList.add("right");fb.innerHTML="✅ <b>Correct!</b> "+q.e;if(!S.ans[b.dataset.q]){S.ans[b.dataset.q]=1;award(10)}}
else{b.classList.add("wrong");b.disabled=true;fb.innerHTML="❌ "+whyWrong(q,j)+" Try again. Hint: "+q.e.split(".")[0]+". <small class=\"ix-rvnote\">🔁 This question will come back in your review.</small>";
rvAdd(key,{t:"q",m:CUR,d:{q:q.q,o:q.o,a:q.a,e:q.e,w:q.w}})}
fb.hidden=false;const all=qs.every((q,k)=>root.querySelector(`[data-q="${id}-${k}"].right`));if(all)onAll()})};
/* ================= games: replay only the misses ================= */
const missBtn=(n)=>n?`<button class="xmiss pri">🔁 Replay only the misses (${n})</button>`:"";
W.pickset=(el,only)=>{const D0=XPK[el.dataset.set],D={...D0,items:SH(only||D0.items)};let n=0,right=0;const miss=[];
const draw=()=>{if(n>=D.items.length){el.innerHTML=`<div class="xgame"><b>${D.t}</b><div class="info">🏆 Done: ${right}/${D.items.length} right first time.${only?" (misses round)":""}</div><div class="ctrl">${missBtn(miss.length)}<button class="xreset">↺ Play again</button></div></div>`;el.querySelector(".xreset").onclick=()=>W.pickset(el);const mb=el.querySelector(".xmiss");if(mb)mb.onclick=()=>W.pickset(el,miss.slice());complete("x-pk-"+el.dataset.set,15,"🎯 Scenario game done! +15 XP");return}
const s=D.items[n];let first=true;el.innerHTML=`<div class="xgame"><b>${D.t}</b> <small>(${n+1}/${D.items.length}${only?", misses only":""})</small><p class="xscen">${s[0]}</p><div class="ctrl">${D.opts.map((o,i)=>`<button data-o="${i}">${o}</button>`).join("")}</div><div class="info xp-info">Pick one.</div></div>`;
el.querySelectorAll("[data-o]").forEach(b=>b.onclick=()=>{const inf=el.querySelector(".xp-info");if(D.opts[+b.dataset.o]==s[1]){if(first)right++;b.classList.add("right");el.querySelectorAll("[data-o]").forEach(x=>x.disabled=true);inf.innerHTML=`✅ <b>${s[1]}.</b> ${s[2]} <button class="xnext">Next ▶</button>`;inf.querySelector(".xnext").onclick=()=>{n++;draw()}}
else{if(first){miss.push(s);rvAdd("pk:"+el.dataset.set+":"+PT(s[0]).slice(0,60),{t:"q",m:CUR,d:{q:D.t+": "+s[0],o:D.opts,a:D.opts.indexOf(s[1]),e:s[2]}})}first=false;b.classList.add("wrong");b.disabled=true;inf.innerHTML="❌ Not quite. "+(s[3]||"Think again about the key clue.")}})};draw()};
W.sortset=(el,only)=>{const D=XSORT[el.dataset.set],I=SH(only||D.items);let ok=0;const done=new Set(),miss=new Set();
el.innerHTML=`<div class="xgame"><b>🧩 ${D.t}</b>${only?" <small>(misses only)</small>":""}<div class="sortg">${I.map((it,i)=>`<div class="sortrow" data-i="${i}"><span class="st">${it[0]}</span><span class="sb">${D.labels.map((l,j)=>`<button data-a="${j}">${l}</button>`).join("")}</span><div class="sfb" hidden></div></div>`).join("")}</div><div class="info xs3">0/${I.length} sorted correctly.</div><div class="ctrl xs4"></div></div>`;
el.querySelectorAll(".sortrow").forEach(row=>row.querySelectorAll("button").forEach(b=>b.onclick=()=>{const i=+row.dataset.i,it=I[i],fb=row.querySelector(".sfb");fb.hidden=false;
if(+b.dataset.a==it[1]){row.querySelectorAll("button").forEach(x=>x.disabled=true);b.classList.add("right");row.classList.add("ok");fb.innerHTML="✅ "+it[2];if(!done.has(i)){done.add(i);ok++}}
else{b.classList.add("wrong");fb.innerHTML="❌ Not quite. Look again at the key feature.";if(!done.has(i)&&!miss.has(i)){miss.add(i);rvAdd("so:"+el.dataset.set+":"+PT(it[0]).slice(0,60),{t:"q",m:CUR,d:{q:`${D.t}: where does “${it[0]}” belong?`,o:D.labels,a:it[1],e:it[2]}})}}
el.querySelector(".xs3").textContent=ok==I.length?`🏆 All sorted! ${I.length-miss.size}/${I.length} right first time.`:`${ok}/${I.length} sorted correctly.`;
if(ok==I.length){complete("x-so-"+el.dataset.set,15,"🧩 Sorting complete! +15 XP");const c=el.querySelector(".xs4");c.innerHTML=missBtn(miss.size)+`<button class="xreset">↺ Play again</button>`;c.querySelector(".xreset").onclick=()=>W.sortset(el);const mb=c.querySelector(".xmiss");if(mb)mb.onclick=()=>W.sortset(el,[...miss].map(k=>I[k]))}}))};
W.pattern=(el,only)=>{const D=XPAT[el.dataset.set];let order=SH(only||D.rows.map((r,i)=>i)),n=0,right=0;const miss=[];
const col=v=>/↑/.test(v)?"var(--bad)":/↓/.test(v)?"var(--acc)":"var(--ok)";
const table=()=>`<div class="tblwrap"><table><tr><th>Cause</th>${D.cols.map(c=>`<th>${c}</th>`).join("")}</tr>${D.rows.map(r=>`<tr><td><b>${r[0]}</b></td>${r[1].map(v=>`<td style="color:${col(v)};font-weight:700">${v}</td>`).join("")}</tr>`).join("")}</table></div>`;
const draw=()=>{if(n>=order.length){el.innerHTML=`<div class="xgame"><b>🔬 ${D.t}</b><div class="info">🏆 ${right}/${order.length} right first time${only?" (misses round)":""}. The full pattern table:</div>${table()}<div class="ctrl">${missBtn(miss.length)}<button class="xreset">↺ Play again</button></div></div>`;el.querySelector(".xreset").onclick=()=>W.pattern(el);const mb=el.querySelector(".xmiss");if(mb)mb.onclick=()=>W.pattern(el,miss.slice());complete("x-pa-"+el.dataset.set,15,"🔬 Patterns mastered! +15 XP");return}
const r=D.rows[order[n]];let first=true;el.innerHTML=`<div class="xgame"><b>🔬 ${D.t}</b> <small>(${n+1}/${order.length}${only?", misses only":""}) Which cause fits these results?</small><div class="xlabs">${D.cols.map((c,i)=>`<span class="xlab"><small>${c}</small><b style="color:${col(r[1][i])}">${r[1][i]}</b></span>`).join("")}</div><div class="ctrl xcol">${D.rows.map((x,i)=>`<button data-i="${i}">${x[0]}</button>`).join("")}</div><div class="info xpa">Pick the cause.</div><button class="xshow">📋 Show the whole table</button></div>`;
el.querySelector(".xshow").onclick=e=>{e.target.outerHTML=table()};
el.querySelectorAll("[data-i]").forEach(b=>b.onclick=()=>{const inf=el.querySelector(".xpa");if(+b.dataset.i==order[n]){if(first)right++;b.classList.add("right");el.querySelectorAll("[data-i]").forEach(x=>x.disabled=true);inf.innerHTML=`✅ <b>${r[0]}.</b> ${r[2]} <button class="xnext">Next ▶</button>`;inf.querySelector(".xnext").onclick=()=>{n++;draw()}}
else{if(first){miss.push(order[n]);rvAdd("pa:"+el.dataset.set+":"+order[n],{t:"q",m:CUR,d:{q:`${D.t}: which cause fits? `+D.cols.map((c,i)=>`${c}: ${r[1][i]}`).join(", "),o:D.rows.map(x=>x[0]),a:order[n],e:r[2]}})}first=false;b.classList.add("wrong");b.disabled=true;inf.textContent="❌ Not this one. Look at the strongest clue first."}})};draw()};
/* ================= step-through diagrams: previous, next and dots ================= */
const _st=W.stepsvg;W.stepsvg=el=>{_st(el);const bs=[...el.querySelectorAll(".ctrl [data-i]")],n=bs.length;if(n<2)return;const seen=new Set([0]);
el.querySelector(".xst").insertAdjacentHTML("afterend",`<div class="ix-stepnav"><button class="ix-prev" type="button">◀ Previous</button><span class="ix-dots" role="group" aria-label="Steps">${bs.map((b,i)=>`<button type="button" class="ix-dot" data-d="${i}" aria-label="Step ${i+1}"></button>`).join("")}</span><span class="ix-cnt"></span><button class="ix-next pri" type="button">Next ▶</button></div>`);
const pv=el.querySelector(".ix-prev"),nx=el.querySelector(".ix-next");const cur=()=>Math.max(0,bs.findIndex(b=>b.classList.contains("on")));
const upd=()=>{const c=cur();seen.add(c);el.querySelectorAll(".ix-dot").forEach((d,i)=>{d.classList.toggle("on",i==c);d.classList.toggle("seen",seen.has(i));d.setAttribute("aria-current",i==c?"step":"false")});pv.disabled=c<=0;nx.disabled=c>=n-1;el.querySelector(".ix-cnt").textContent=`${c+1} / ${n}`};
bs.forEach(b=>b.addEventListener("click",()=>setTimeout(upd)));pv.onclick=()=>{const c=cur();if(c>0)bs[c-1].click()};nx.onclick=()=>{const c=cur();if(c<n-1)bs[c+1].click()};
el.querySelectorAll(".ix-dot").forEach(d=>d.onclick=()=>bs[+d.dataset.d].click());upd()};
/* ================= hormone axis simulator ================= */
const AX={thy:{n:"Thyroid axis",t:["Hypothalamus","Anterior pituitary","Thyroid gland"],h:["thyrotropin-releasing hormone","thyroid-stimulating hormone","free thyroxine"]},
adr:{n:"Adrenal axis",t:["Hypothalamus","Anterior pituitary","Adrenal cortex"],h:["corticotropin-releasing hormone","adrenocorticotropic hormone","cortisol"]},
gh:{n:"Growth hormone axis",t:["Hypothalamus","Anterior pituitary","Liver"],h:["growth hormone-releasing hormone","growth hormone","insulin-like growth factor 1"]}};
const NN={thy:["N","N","N"],adr:["N","N","N"],gh:["N","N","N"]};
const SC=[
{id:"normal",ax:"all",l:"Healthy person",v:{},t:"Each level is held steady by negative feedback: the end hormone switches off the hypothalamus and the pituitary."},
{id:"pthy",ax:"thy",l:"Primary hypothyroidism (for example Hashimoto thyroiditis)",at:2,v:{thy:["?","↑","↓"]},t:"The thyroid itself fails. Free thyroxine falls, feedback is lost, and thyroid-stimulating hormone rises. A raised thyroid-stimulating hormone is the most sensitive sign.",go:"t6a"},
{id:"cthy",ax:"thy",l:"Central hypothyroidism (pituitary)",at:1,v:{thy:["?","↓N","↓"]},t:"The pituitary cannot answer. Thyroid-stimulating hormone is low or inappropriately normal while free thyroxine is low, so a thyroid-stimulating hormone test alone misses it: always read free thyroxine too.",go:"p4b"},
{id:"tthy",ax:"thy",l:"Hypothalamic hypothyroidism",at:0,v:{thy:["↓","↓N","↓"]},t:"Too little thyrotropin-releasing hormone, so the pituitary is under-driven. The blood picture looks like central hypothyroidism.",go:"p4a"},
{id:"graves",ax:"thy",l:"Graves disease",at:2,v:{thy:["?","↓","↑"]},t:"Stimulating antibodies drive the thyroid directly. High free thyroxine suppresses the pituitary, so thyroid-stimulating hormone is very low.",go:"t1b"},
{id:"lt4",ax:"thy",l:"Too much levothyroxine",at:3,v:{thy:["?","↓","↑"]},t:"Tablets, not the gland, raise free thyroxine; feedback suppresses thyroid-stimulating hormone. Same pattern as Graves disease, so the history matters.",go:"t6d"},
{id:"tshoma",ax:"thy",l:"Thyroid-stimulating hormone-secreting pituitary adenoma",at:1,v:{thy:["?","↑N","↑"]},t:"The tumour ignores feedback: free thyroxine is high but thyroid-stimulating hormone is normal or high instead of suppressed. Exclude laboratory interference and thyroid hormone resistance.",go:"t1j"},
{id:"rth",ax:"thy",l:"Thyroid hormone resistance",at:3,v:{thy:["?","↑N","↑"]},t:"The receptors respond poorly, so the pituitary needs more hormone before it switches off: free thyroxine high with a normal or high thyroid-stimulating hormone.",go:"t6f"},
{id:"padr",ax:"adr",l:"Primary adrenal insufficiency (Addison disease)",at:2,v:{adr:["?","↑","↓"]},t:"The adrenal cortex is destroyed. Cortisol falls and adrenocorticotropic hormone rises (dark skin). Aldosterone is lost too: salt loss and high potassium.",go:"d2"},
{id:"sadr",ax:"adr",l:"Secondary adrenal insufficiency (pituitary)",at:1,v:{adr:["?","↓N","↓"]},t:"Adrenocorticotropic hormone is low or inappropriately normal, so cortisol is low. Aldosterone is kept (renin and angiotensin control it), so potassium stays normal and the skin is not dark.",go:"d2"},
{id:"steroid",ax:"adr",l:"After months of steroid tablets",at:3,v:{adr:["↓","↓","↓"]},t:"The tablets do the work, so the hypothalamus and pituitary switch off and the adrenal's own cortisol output falls. Stopping suddenly can cause adrenal crisis: taper.",go:"d9"},
{id:"cushd",ax:"adr",l:"Cushing disease (pituitary adenoma)",at:1,v:{adr:["?","↑N","↑"]},t:"The corticotroph adenoma makes adrenocorticotropic hormone despite high cortisol: adrenocorticotropic hormone is normal or high, not suppressed.",go:"d3"},
{id:"cusha",ax:"adr",l:"Cortisol-secreting adrenal adenoma",at:2,v:{adr:["?","↓","↑"]},t:"The adrenal makes cortisol on its own; feedback suppresses adrenocorticotropic hormone.",go:"d3"},
{id:"ect",ax:"adr",l:"Ectopic adrenocorticotropic hormone (for example a lung tumour)",at:3,v:{adr:["?","↑","↑"]},t:"A tumour outside the pituitary makes adrenocorticotropic hormone, often very high, so cortisol is very high; low potassium is common.",go:"d3"},
{id:"acro",ax:"gh",l:"Acromegaly (somatotroph adenoma)",at:1,v:{gh:["?","↑","↑"]},t:"Growth hormone is high and is not suppressed by glucose; insulin-like growth factor 1 is high and is the screening test.",go:"p3b"},
{id:"ghrh",ax:"gh",l:"Tumour making growth hormone-releasing hormone (rare)",at:3,v:{gh:["↑","↑","↑"]},t:"A tumour elsewhere drives the pituitary, so growth hormone and insulin-like growth factor 1 rise.",go:"p3b"},
{id:"ghd",ax:"gh",l:"Growth hormone deficiency",at:1,v:{gh:["?","↓","↓N"]},t:"Growth hormone comes in pulses, so a single value means little: a stimulation test is needed. Insulin-like growth factor 1 is low or can be normal.",go:"p4b"},
{id:"laron",ax:"gh",l:"Growth hormone resistance (Laron syndrome)",at:2,v:{gh:["?","↑","↓"]},t:"The growth hormone receptor does not work, so the liver makes little insulin-like growth factor 1 and growth hormone rises."},
{id:"hypopit",ax:"all",l:"Pituitary failure (hypopituitarism)",at:1,v:{thy:["?","↓N","↓"],adr:["?","↓N","↓"],gh:["?","↓","↓N"]},t:"Several axes fail at the pituitary level. Every pituitary hormone is low or inappropriately normal for its low end hormone. Replace cortisol before thyroxine.",go:"p4c"}];
const LV={"↑":["high","up"],"↓":["low","down"],"N":["normal","n"],"↓N":["low or normal","dn"],"↑N":["normal or high","un"],"?":["not measured","q"]};
const lv=v=>{const q=/\?$/.test(v)&&v.length>1,b=v.replace("?","")||"?";return {b,q,txt:LV[b][0]+(q?" (rarely measured)":""),c:LV[b][1]}};
function axis(el,preset){let sc=SC.find(s=>s.id==preset)||SC[0],mode="see",guess={};
const axesOf=s=>s.ax=="all"?["thy","adr","gh"]:[s.ax];
const draw=()=>{const show=axesOf(sc).length?axesOf(sc):["thy"];const vals=k=>(sc.v[k]||NN[k]);
el.innerHTML=`<div class="xgame ix-axis"><b>🧪 Hormone axis simulator</b><p class="ix-sub">Pick a situation and watch the feedback loop. 💡 Try “Predict first” to test yourself.</p>
<label class="xci"><span>Situation</span><select class="ix-sc">${["thy","adr","gh","all"].map(a=>`<optgroup label="${a=="all"?"Several axes":AX[a].n}">${SC.filter(s=>s.ax==a).map(s=>`<option value="${s.id}" ${s.id==sc.id?"selected":""}>${s.l}</option>`).join("")}</optgroup>`).join("")}</select></label>
<div class="ctrl"><button data-mode="see" class="${mode=="see"?"on":""}">👀 Show me</button><button data-mode="guess" class="${mode=="guess"?"on":""}">🤔 Predict first</button></div>
<div class="ix-axes">${show.map(k=>{const A=AX[k],v=vals(k);return `<div class="ix-ax"><h4>${A.n}</h4>${A.t.map((tier,i)=>{const L=lv(v[i]);const hide=mode=="guess"&&i>0&&!guess.done;const brk=sc.at===i&&axesOf(sc).includes(k);
return `${i?`<div class="ix-arrow ${L.c=="down"||L.c=="dn"?"weak":L.c=="up"?"strong":""}" aria-hidden="true">▼</div>`:""}<div class="ix-tier ${brk?"brk":""}"><small>${tier}${brk?" · ⚡ problem here":""}</small><span>${A.h[i]}</span>${hide?`<span class="ix-guess">${["↑","N","↓"].map(g=>`<button data-g="${k}${i}${g}" class="${guess[k+i]==g?"on":""}" aria-label="${LV[g][0]}">${g=="N"?"normal":g=="↑"?"↑ high":"↓ low"}</button>`).join("")}</span>`:`<b class="ix-lv lv-${L.c}">${({"↑":"↑","↓":"↓","N":"=","↓N":"↓ / =","↑N":"↑ / =","?":"–"})[L.b]} <em>${L.txt}</em></b>`}</div>`}).join("")}<div class="ix-fb">↺ ${sc.at===3&&axesOf(sc).includes(k)?"Problem outside the axis (tablets, receptors or a tumour elsewhere)":"Negative feedback: "+A.h[2]+" switches off the levels above"}</div></div>`}).join("")}</div>
${mode=="guess"&&!guess.done?`<div class="ctrl"><button class="pri ix-check">Check my prediction</button></div>`:""}<div class="info ix-out">${mode=="guess"&&!guess.done?"Predict the pituitary hormone and the end hormone for each axis shown, then check.":(guess.res||"")+`<b>${sc.l}:</b> ${sc.t}${sc.go&&OK(sc.go)?` <a href="#" data-fxgo="${sc.go}">Open ${E(MOD(sc.go).n+" "+MOD(sc.go).title)} →</a>`:""}`}</div>
<small>Built by MedLearn from the lecture physiology. “Not measured”: hypothalamic hormones are not measured in routine practice, so no direction is claimed. Arrows show the typical direction; real results depend on the laboratory and the stage of the disease.</small></div>`;
el.querySelector(".ix-sc").onchange=e=>{sc=SC.find(s=>s.id==e.target.value);guess={};draw()};
el.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{mode=b.dataset.mode;guess={};draw()});
el.querySelectorAll("[data-g]").forEach(b=>b.onclick=()=>{const k=b.dataset.g.slice(0,-1);guess[k]=b.dataset.g.slice(-1);draw()});
const ck=el.querySelector(".ix-check");if(ck)ck.onclick=()=>{let ok=0,tot=0,miss=[];show.forEach(k=>{const v=vals(k);[1,2].forEach(i=>{const b=lv(v[i]).b;if(b=="?")return;tot++;const g=guess[k+i];const good=g&&(b==g||(b=="↓N"&&(g=="↓"||g=="N"))||(b=="↑N"&&(g=="↑"||g=="N")));if(good)ok++;else miss.push(AX[k].h[i])})});
guess.done=1;guess.res=`${ok==tot?"✅":"🟡"} You predicted ${ok} of ${tot} correctly.${miss.length?" Look again at: "+miss.join(", ")+".":""}<br>`;if(ok==tot)complete("ix-axis-"+sc.id,10,"🧪 Axis predicted! +10 XP");draw()}};draw()}
/* ================= lab-value interpreter cards ================= */
function labThy(el){el.innerHTML=`<div class="xgame ix-lab"><b>🔬 Thyroid tests: what does this pair mean?</b><p class="ix-sub">Enter the result and your laboratory's range. Always read the two values together.</p><div class="xcalc">
<label class="xci"><span>Thyroid-stimulating hormone (mIU/L)</span><input type="number" step="any" inputmode="decimal" data-v="tsh" value="6.8"></label>
<label class="xci"><span>Range</span><span class="ix-rng"><input type="number" step="any" inputmode="decimal" data-v="tl" value="0.5" aria-label="lower limit"> to <input type="number" step="any" inputmode="decimal" data-v="th" value="4.5" aria-label="upper limit"></span></label>
<label class="xci"><span>Free thyroxine (pmol/L)</span><input type="number" step="any" inputmode="decimal" data-v="ft4" value="14"></label>
<label class="xci"><span>Range</span><span class="ix-rng"><input type="number" step="any" inputmode="decimal" data-v="fl" value="9" aria-label="lower limit"> to <input type="number" step="any" inputmode="decimal" data-v="fh" value="19" aria-label="upper limit"></span></label></div>
<div class="info ix-res" aria-live="polite"></div><small>A teaching aid, not a diagnosis. Ranges differ between laboratories and in pregnancy.</small></div>`;
const run=()=>{const v={};el.querySelectorAll("[data-v]").forEach(i=>v[i.dataset.v]=parseFloat(i.value));const out=el.querySelector(".ix-res");if([v.tsh,v.ft4,v.tl,v.th,v.fl,v.fh].some(isNaN)){out.textContent="Enter all values.";return}
const T=v.tsh>v.th?"H":v.tsh<v.tl?"L":"N",F=v.ft4>v.fh?"H":v.ft4<v.fl?"L":"N";const lab=x=>({H:"high",L:"low",N:"normal"})[x];
const R={HL:["Primary hypothyroidism","The gland is failing and the pituitary pushes harder. Usual cause where iodine is sufficient: chronic autoimmune thyroiditis (check thyroid peroxidase antibodies).","t6a"],
HN:["Subclinical hypothyroidism (or recovery phase)","Repeat in 6 to 12 weeks. Also seen when recovering from thyroiditis or from a non-thyroidal illness, and with laboratory interference.","t6c"],
LH:["Thyrotoxicosis from the thyroid","Find the cause: antibodies, uptake scan (overactive gland versus leaking gland), Doppler ultrasound.","t1d"],
LN:["Subclinical hyperthyroidism, or triiodothyronine toxicosis","Measure free triiodothyronine. Also think of severe illness, steroid or dopamine treatment, and the first trimester of pregnancy.","t1a"],
LL:["Central hypothyroidism or non-thyroidal illness","Low free thyroxine without a high thyroid-stimulating hormone: think of the pituitary (check the other axes) or a very sick patient (sick euthyroid).","p4b"],
NL:["Central hypothyroidism or non-thyroidal illness","A normal thyroid-stimulating hormone is inappropriate for a low free thyroxine: check the pituitary or consider severe illness.","p4b"],
HH:["High free thyroxine without a suppressed thyroid-stimulating hormone","Exclude laboratory interference and erratic levothyroxine intake first, then think of a thyroid-stimulating hormone-secreting adenoma or thyroid hormone resistance.","t1j"],
NH:["High free thyroxine without a suppressed thyroid-stimulating hormone","Exclude laboratory interference, a recent levothyroxine dose, amiodarone or heparin effects; then think of a thyroid-stimulating hormone-secreting adenoma or thyroid hormone resistance.","t1j"],
NN:["Normal thyroid function","Both values in range: thyroid dysfunction is unlikely (unless the pituitary is diseased or the patient is very ill).","t3a"]}[T+F];
out.innerHTML=`Thyroid-stimulating hormone <b>${lab(T)}</b>, free thyroxine <b>${lab(F)}</b> → <b>${R[0]}</b>. ${R[1]}${OK(R[2])?` <a href="#" data-fxgo="${R[2]}">Open ${E(MOD(R[2]).n+" "+MOD(R[2]).title)} →</a>`:""}`};
let used=0;el.querySelectorAll("[data-v]").forEach(i=>i.oninput=()=>{run();if(++used==3)complete("ix-labthy",10,"🔬 Interpreter explored! +10 XP")});run()}
function labAdr(el){el.innerHTML=`<div class="xgame ix-lab"><b>🔬 Morning cortisol and adrenocorticotropic hormone</b><p class="ix-sub">Blood taken around 8 in the morning. The cut-offs below are the ones used in the lectures; they depend on the assay.</p><div class="xcalc">
<label class="xci"><span>Morning cortisol</span><span class="ix-rng"><input type="number" step="any" inputmode="decimal" data-v="c" value="110" aria-label="cortisol"><select data-v="u" aria-label="unit"><option value="n">nmol/L</option><option value="u">µg/dl</option></select></span></label>
<label class="xci"><span>Adrenocorticotropic hormone (pg/ml)</span><input type="number" step="any" inputmode="decimal" data-v="a" value="150"></label>
<label class="xci"><span>Its range</span><span class="ix-rng"><input type="number" step="any" inputmode="decimal" data-v="al" value="7.2" aria-label="lower limit"> to <input type="number" step="any" inputmode="decimal" data-v="ah" value="63" aria-label="upper limit"></span></label>
<label class="xci xcc"><input type="checkbox" data-v="pill"> <span>On the contraceptive pill or pregnant</span></label><label class="xci xcc"><input type="checkbox" data-v="ster"> <span>Taking steroid tablets, inhalers or injections</span></label><label class="xci xcc"><input type="checkbox" data-v="ill"> <span>Acutely ill (vomiting, low blood pressure)</span></label></div>
<div class="info ix-res" aria-live="polite"></div><small>A teaching aid, not a diagnosis. 1 µg/dl of cortisol is about 27.6 nmol/L.</small></div>`;
const run=()=>{const g=k=>el.querySelector(`[data-v="${k}"]`);const raw=parseFloat(g("c").value),u=g("u").value,a=parseFloat(g("a").value),al=parseFloat(g("al").value),ah=parseFloat(g("ah").value);const out=el.querySelector(".ix-res");
if([raw,a,al,ah].some(isNaN)){out.textContent="Enter all values.";return}const c=u=="u"?raw*27.6:raw;const A=a>ah?"high":a<al?"low":"normal";let h=`Cortisol ≈ <b>${Math.round(c)} nmol/L</b> (${(c/27.6).toFixed(1)} µg/dl), adrenocorticotropic hormone <b>${A}</b>. `,go="d2";
if(g("ster").checked)h+="⚠️ Steroid treatment suppresses the axis, and some steroids (for example prednisolone) are picked up by the cortisol test, so this result cannot be read as it stands. Ask about the last dose. ";
if(c<140){h+=A=="high"?"→ <b>Primary adrenal insufficiency is very likely</b> (low cortisol with high adrenocorticotropic hormone, the Endocrine Society 2016 pattern). Check renin, aldosterone, sodium and potassium; confirm with the short stimulation test when safe.":"→ <b>Low cortisol without a high adrenocorticotropic hormone: secondary or tertiary adrenal insufficiency</b> (pituitary, hypothalamus or steroid suppression). Check the other pituitary axes.";if(A!="high")go="p4b"}
else if(c<500){h+="→ <b>Not conclusive.</b> Do the short stimulation test: a normal peak is above about 500–550 nmol/L (18–20 µg/dl), lower with newer assays."+(A=="high"?" A high adrenocorticotropic hormone already points to early primary insufficiency.":"")}
else{h+="→ <b>Adrenal insufficiency is unlikely</b> at this level (the exact cut-off depends on the assay). A single morning cortisol cannot diagnose Cushing syndrome; use the screening tests if you suspect it.";go=c>700?"d3":"d2"}
if(g("pill").checked)h+=" 💡 Oestrogen raises cortisol-binding globulin, so total cortisol reads higher: a “normal” value can hide insufficiency.";
if(g("ill").checked&&c<500)h+=" 🚑 If adrenal crisis is possible, give hydrocortisone straight away: do not wait for results.";
out.innerHTML=h+(OK(go)?` <a href="#" data-fxgo="${go}">Open ${E(MOD(go).n+" "+MOD(go).title)} →</a>`:"")};
let used=0;el.querySelectorAll("[data-v]").forEach(i=>i.oninput=i.onchange=()=>{run();if(++used==3)complete("ix-labadr",10,"🔬 Interpreter explored! +10 XP")});run()}
/* ================= sheets (reuse the publish10 overlay style) ================= */
function sheet(id,title,html){let o=document.getElementById(id);if(!o){document.body.insertAdjacentHTML("beforeend",`<div id="${id}" class="fx-sheet" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="fx-panel"><div class="fx-shead"><h2></h2><button class="fx-x" data-fxclose aria-label="Close">✕</button></div><div class="fx-body"></div></div></div>`);o=document.getElementById(id);o.addEventListener("click",e=>{if(e.target===o){$$(".fx-sheet.open").forEach(s=>s.classList.remove("open"));document.body.classList.remove("fx-noscroll")}})}
$$(".fx-sheet.open").forEach(s=>s.classList.remove("open"));o.querySelector("h2").textContent=title;const b=o.querySelector(".fx-body");b.innerHTML=html;o.classList.add("open");document.body.classList.add("fx-noscroll");b.scrollTop=0;setTimeout(()=>o.querySelector(".fx-x").focus(),20);return b}
