function review(early){let items=due();if(!items.length&&early)items=Object.entries(RV).sort((a,b)=>a[1].due<b[1].due?-1:1);items=SH(items.slice(0,early?10:999)).slice(0,10);
if(!items.length){const tot=Object.keys(RV).length;sheet("ix-tools","🔁 Today's 10",`<button class="ix-back" data-ixt="menu">← All study tools</button><p>🎉 <b>Nothing is due today.</b></p><p>Missed quiz questions, game rounds and flashcards you mark “unsure” or “didn't know” land here. They come back after 1, 3 and 7 days, and leave once you get them right each time.</p>${tot?`<p>${tot} item${tot==1?"":"s"} waiting for later days.</p><button class="pri" data-ixt="early">Practise early anyway</button>`:""}`);return}
let n=0,right=0;const b=sheet("ix-tools","🔁 Today's 10",`<div class="ix-rv"></div>`).querySelector(".ix-rv");
const next=()=>{if(n>=items.length){bump();b.innerHTML=`<p>🏁 <b>Round finished: ${right} of ${items.length} right.</b></p><p>${due().length?`${due().length} more due today.`:"All done for today."} Right answers come back later (1, 3, then 7 days); misses come back tomorrow.</p><div class="ctrl">${due().length?`<button class="pri" data-ixt="review">Next 10</button>`:""}<button data-ixt="menu">← Study tools</button></div>`;return}
const [key,it]=items[n],m=MOD(it.m),src=m?`<small class="ix-src">From ${E(m.n+" "+m.title)}</small>`:"";
if(it.t=="f"){b.innerHTML=`<div class="ix-rvh">${n+1} / ${items.length} · flashcard</div>${src}<div class="ix-fc"><div>${E(it.d.f)}</div><div class="ix-fcb" hidden>${E(it.d.b)}</div></div><div class="ctrl"><button class="pri ix-show">Show the answer</button></div>`;
b.querySelector(".ix-show").onclick=()=>{b.querySelector(".ix-fcb").hidden=false;b.querySelector(".ctrl").innerHTML=`<button data-c="2">😎 Knew it</button><button data-c="1">🤔 Unsure</button><button data-c="0">😵 Didn't know</button>`;b.querySelectorAll("[data-c]").forEach(x=>x.onclick=()=>{if(x.dataset.c=="2"){right++;rvRight(key)}else if(x.dataset.c=="1"){RV[key].box=Math.max(1,RV[key].box);RV[key].due=DAY(1);rvSave()}else rvWrong(key);n++;next()})};return}
const q=it.d,ord=SH(q.o.map((o,i)=>i));let first=true;b.innerHTML=`<div class="ix-rvh">${n+1} / ${items.length} · question</div>${src}<p class="ix-q">${TM(q.q)}</p><div class="ix-opts">${ord.map(j=>`<button class="opt" data-j="${j}">${TM(q.o[j])}</button>`).join("")}</div><div class="fb ix-rfb" hidden></div>`;
b.querySelectorAll(".opt").forEach(o=>o.onclick=()=>{const j=+o.dataset.j,fb=b.querySelector(".ix-rfb");fb.hidden=false;if(j==q.a){o.classList.add("right");b.querySelectorAll(".opt").forEach(x=>x.disabled=true);let when="";if(first){right++;when=rvRight(key)}else rvWrong(key);
fb.innerHTML=`✅ ${TM(q.e)}<br><small>${first?(when=="mastered"?"🏆 Mastered: it leaves your review.":"Comes back "+when+"."):"Comes back tomorrow."}</small> <button class="pri ix-nx">Next ▶</button>`;fb.querySelector(".ix-nx").onclick=()=>{n++;next()}}
else{first=false;o.classList.add("wrong");o.disabled=true;fb.innerHTML="❌ "+whyWrong(q,j)+" Try again."}})};next()}
