const EXT=60;
function pool(areas){const P=[];COURSE.modules.forEach(m=>{if(!OK(m.id)||!areas.includes(AREA(m.id)))return;LESSONS[m.id].cards.forEach(c=>(c.quiz||[]).forEach((q,i)=>{if(q&&q.o&&q.o.length>1&&typeof q.a=="number")P.push({m:m.id,c:c.id,ct:PT(c.title),k:c.id+"-"+i,q})}))});return P}
function examSetup(){const hist=J("ml_exams",[]);const b=sheet("ix-tools","📝 Exam mode",`<button class="ix-back" data-ixt="menu">← All study tools</button><p>Mixed questions from the lectures you choose. One minute per question, no feedback until the end, just like the real thing.</p>
<fieldset class="ix-fs"><legend>Lectures</legend>${AREAS.map((a,i)=>`<label class="xci xcc"><input type="checkbox" data-ea="${i}" checked> <span>${a} (${pool([a]).length} questions)</span></label>`).join("")}</fieldset>
<label class="xci"><span>Number of questions</span><select class="ix-en"><option>10</option><option selected>20</option><option>30</option></select></label><div class="ctrl"><button class="pri ix-go">▶ Start the exam</button></div>
${hist.length?`<p><b>Recent scores:</b> ${hist.slice(-5).reverse().map(h=>`${h.s}/${h.n} (${h.d})`).join(" · ")}</p>`:""}`);
b.querySelector(".ix-go").onclick=()=>{const ar=[...b.querySelectorAll("[data-ea]:checked")].map(x=>AREAS[+x.dataset.ea]);if(!ar.length){toast("Pick at least one lecture area");return}exam(ar,+b.querySelector(".ix-en").value)}}
let ETIMER=null;
function exam(ar,N){let fin=false;const P=SH(pool(ar)).slice(0,N);N=P.length;const ans=[];let n=0;const end=Date.now()+N*EXT*1000;const b=sheet("ix-tools","📝 Exam mode",`<div class="ix-ehead"><span class="ix-eq"></span><span class="ix-clock" aria-live="off"></span><button class="ix-stop">Finish now</button></div><div class="ix-ebody"></div>`);
const clock=()=>{if(!document.querySelector("#ix-tools.open .ix-clock")){clearInterval(ETIMER);fin=true;return}const s=Math.max(0,Math.round((end-Date.now())/1000));const c=b.querySelector(".ix-clock");if(!c){clearInterval(ETIMER);return}c.textContent=`⏱️ ${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;c.classList.toggle("low",s<60);if(s<=0)finish()};
clearInterval(ETIMER);ETIMER=setInterval(clock,1000);clock();b.querySelector(".ix-stop").onclick=()=>finish();
const show=()=>{if(n>=N)return finish();const it=P[n],m=MOD(it.m),ord=SH(it.q.o.map((o,i)=>i));b.querySelector(".ix-eq").textContent=`Question ${n+1} of ${N}`;
b.querySelector(".ix-ebody").innerHTML=`<small class="ix-src">${E(m.n+" "+m.title)} › ${E(it.ct)}</small><p class="ix-q">${TM(it.q.q)}</p><div class="ix-opts">${ord.map(j=>`<button class="opt" data-j="${j}">${TM(it.q.o[j])}</button>`).join("")}</div><div class="ctrl"><button class="ix-skip">Skip</button></div>`;
b.querySelectorAll(".opt").forEach(o=>o.onclick=()=>{ans[n]=+o.dataset.j;n++;show()});b.querySelector(".ix-skip").onclick=()=>{ans[n]=null;n++;show()}};
const finish=()=>{if(fin)return;fin=true;clearInterval(ETIMER);let s=0;const wrong=[],weak={};P.forEach((it,i)=>{if(ans[i]===it.q.a)s++;else{wrong.push([it,ans[i]]);weak[it.m]=(weak[it.m]||0)+1;rvAdd("q:"+it.m+":"+it.k,{t:"q",m:it.m,d:{q:it.q.q,o:it.q.o,a:it.q.a,e:it.q.e,w:it.q.w}})}});
const used=Math.round((N*EXT*1000-Math.max(0,end-Date.now()))/1000);const h=J("ml_exams",[]);h.push({d:DAY(),s,n:N});SV("ml_exams",h.slice(-20));bump();
const pct=N?Math.round(100*s/N):0;b.innerHTML=`<p class="ix-score"><b>${s} / ${N}</b> (${pct} %) in ${Math.floor(used/60)} min ${used%60} s ${pct>=80?"🏆":pct>=60?"👍":"💪"}</p>
${Object.keys(weak).length?`<p><b>Go back to:</b></p><ul class="ix-weak">${Object.entries(weak).sort((a,b)=>b[1]-a[1]).map(([m,c])=>`<li><a href="#" data-fxgo="${m}">${E(MOD(m).n+" "+MOD(m).title)}</a> (${c} missed)</li>`).join("")}</ul>`:"<p>🎉 No misses.</p>"}
${wrong.length?`<details open><summary><b>Review your misses</b> (they are now in Today's 10)</summary>${wrong.map(([it,a])=>`<div class="ix-mi"><p class="ix-q">${TM(it.q.q)}</p><p>${a==null?"⏭️ Skipped or out of time.":`❌ Your answer: ${TM(it.q.o[a])}`}<br>✅ Right answer: <b>${TM(it.q.o[it.q.a])}</b></p><p class="ix-e">${TM(it.q.e)}</p></div>`).join("")}</details>`:""}
<div class="ctrl"><button class="pri" data-ixt="exam">New exam</button><button data-ixt="menu">← Study tools</button></div>`};show()}
/* ================= focus timer ================= */
const TK="ml_timer";let TMR=J(TK,null),TINT=null;
function timerPanel(){const t=TMR;sheet("ix-tools","⏱️ Focus timer",`<button class="ix-back" data-ixt="menu">← All study tools</button><p>Work in short blocks, then take a real break. 💡 Pair it with 🎯 Focus mode.</p><div class="ctrl">${[[25,5],[15,3],[10,2]].map(([f,b])=>`<button data-ixtm="${f},${b}">${f} min focus + ${b} min break</button>`).join("")}</div>${t?`<p>Running: ${t.ph=="f"?"focus":"break"} block. Use the timer pill at the bottom of the screen to pause or stop.</p><button data-ixtstop>⏹ Stop the timer</button>`:""}`)}
function tStart(f,b){TMR={f,b,ph:"f",end:Date.now()+f*60000,pause:null};SV(TK,TMR);tLoop();toast(`⏱️ ${f}-minute focus block started`);$$(".fx-sheet.open").forEach(s=>s.classList.remove("open"));document.body.classList.remove("fx-noscroll")}
function tStop(){TMR=null;LS.removeItem(TK);clearInterval(TINT);const p=$("#ix-tpill");if(p)p.remove()}
function tLoop(){clearInterval(TINT);if(!TMR)return;let p=$("#ix-tpill");if(!p){document.body.insertAdjacentHTML("beforeend",`<div id="ix-tpill" class="ix-tpill" role="timer"><span class="ix-tlab"></span><button class="ix-tp" aria-label="Pause or resume">⏸</button><button class="ix-tx" aria-label="Stop timer">✕</button></div>`);p=$("#ix-tpill");p.querySelector(".ix-tx").onclick=tStop;p.querySelector(".ix-tp").onclick=()=>{if(TMR.pause){TMR.end=Date.now()+TMR.pause;TMR.pause=null}else TMR.pause=TMR.end-Date.now();SV(TK,TMR);tick()}}
const tick=()=>{if(!TMR)return;const left=TMR.pause!=null?TMR.pause:TMR.end-Date.now();if(left<=0&&TMR.pause==null){if(TMR.ph=="f"){TMR.ph="b";TMR.end=Date.now()+TMR.b*60000;toast(`☕ Break: ${TMR.b} minutes. Stand up, drink water, look away from the screen.`);bump()}else{TMR.ph="f";TMR.end=Date.now()+TMR.f*60000;TMR.pause=TMR.f*60000;toast("🔔 Break over. Press ▶ when you are ready for the next block.")}SV(TK,TMR)}
const s=Math.max(0,Math.ceil((TMR.pause!=null?TMR.pause:TMR.end-Date.now())/1000));p.querySelector(".ix-tlab").textContent=`${TMR.ph=="f"?"🎯 Focus":"☕ Break"} ${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;p.querySelector(".ix-tp").textContent=TMR.pause!=null?"▶":"⏸";p.classList.toggle("brk",TMR.ph=="b")};TINT=setInterval(tick,1000);tick()}
/* ================= hotspot quizzes on labelled pictures ================= */
function hotspot(box,name,src){const P=IXHS[name];if(!P)return;let order=SH(P.map((p,i)=>i)),n=0,right=0,tries=0;const miss=[];
const draw=()=>{if(n>=order.length){box.innerHTML=`<div class="info">🏆 ${right} of ${order.length} found first time.</div><div class="ctrl">${miss.length?`<button class="pri ix-hm">🔁 Replay only the misses (${miss.length})</button>`:""}<button class="ix-hr">↺ Play again</button><button class="ix-hc">Close</button></div>`;box.querySelector(".ix-hr").onclick=()=>{order=SH(P.map((p,i)=>i));reset()};const hm=box.querySelector(".ix-hm");if(hm)hm.onclick=()=>{order=SH(miss.splice(0));reset()};box.querySelector(".ix-hc").onclick=()=>{box.remove()};complete("ix-hs-"+name,10,"🎯 Hotspot quiz done! +10 XP");return}
const t=P[order[n]];tries=0;box.innerHTML=`<div class="ix-hq"><b>Tap: ${E(t[0])}</b> <small>(${n+1}/${order.length})</small></div><div class="ix-himg"><img src="${src}" alt="Unlabelled version of the picture above, for the hotspot quiz" draggable="false"></div><div class="info ix-hfb">Tap the spot on the picture.</div>`;
const wrap=box.querySelector(".ix-himg"),img=wrap.querySelector("img");
img.onclick=e=>{const r=img.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1280,y=(e.clientY-r.top)/r.height*720;let best=-1,bd=1e9;P.forEach((p,i)=>{const d=Math.hypot(p[1]-x,p[2]-y);if(d<bd){bd=d;best=i}});
const fb=box.querySelector(".ix-hfb");const mark=(px,py,cls)=>wrap.insertAdjacentHTML("beforeend",`<span class="ix-hdot ${cls}" style="left:${px/12.8}%;top:${py/7.2}%"></span>`);
if(best==order[n]&&bd<120){mark(t[1],t[2],"ok");if(!tries)right++;fb.innerHTML=`✅ Found it. <button class="pri ix-hn">Next ▶</button>`;img.onclick=null;fb.querySelector(".ix-hn").onclick=()=>{n++;draw()}}
else{tries++;mark(x,y,"no");if(tries==1)miss.push(order[n]);if(tries>=2){mark(t[1],t[2],"ok");fb.innerHTML=`It is at the green dot${best!=order[n]&&bd<120?`; you tapped: ${E(P[best][0])}`:""}. <button class="ix-hn">Next ▶</button>`;img.onclick=null;fb.querySelector(".ix-hn").onclick=()=>{n++;draw()}}else fb.textContent=best!=order[n]&&bd<120?`❌ That is: ${P[best][0]}. Try again.`:"❌ Not quite there. Try again."}}};
const reset=()=>{n=0;right=0;draw()};draw()}
function addHotspots(){$$("#content figure img").forEach(img=>{const m=(img.getAttribute("src")||"").match(/([\w-]+)-labelled\.jpg$/);if(!m||!IXHS[m[1]])return;const fig=img.closest("figure");if(!fig||fig.nextElementSibling&&fig.nextElementSibling.classList.contains("ix-hbtn"))return;
fig.insertAdjacentHTML("afterend",`<button class="ix-hbtn" type="button" title="Needs a mouse or a touch screen">🎯 Hotspot quiz: find the ${IXHS[m[1]].length} labelled parts on the unlabelled picture</button>`);const btn=fig.nextElementSibling;
btn.onclick=()=>{let box=btn.nextElementSibling;if(box&&box.classList.contains("ix-hbox"))return box.scrollIntoView({block:"nearest"});btn.insertAdjacentHTML("afterend",`<div class="ix-hbox xgame"></div>`);hotspot(btn.nextElementSibling,m[1],img.getAttribute("src").replace(/-labelled\.jpg$/,".png"))}})}
