const STOP=new Set("because between without against through before should their there which these those about other being after where while never always within under often usually".split(" "));
function keywords(t){const seen=new Set(),out=[];(PT(t).toLowerCase().match(/[a-z][a-z-]{5,}/g)||[]).forEach(w=>{const s=w.slice(0,6);if(STOP.has(w)||seen.has(s))return;seen.add(s);out.push(w)});return out.slice(0,12)}
function explain(cardEl,cd){if(cardEl.querySelector(".ix-explain"))return;const key=CUR+":"+cd.id,X=J("ml_explain",{});const rc=cardEl.querySelector(".recap");if(!rc)return;
rc.insertAdjacentHTML("afterend",`<details class="ix-explain"${X[key]?" open":""}><summary>✍️ Explain it back: one or two sentences in your own words</summary><textarea rows="3" aria-label="Your explanation" placeholder="Pretend you are explaining this step to a friend…">${E(X[key]||"")}</textarea><div class="ctrl"><button class="ix-cmp">Compare with the recap</button><small class="ix-saved"></small></div><div class="ix-cmpout" hidden></div></details>`);
const ta=cardEl.querySelector(".ix-explain textarea");let tt;ta.oninput=()=>{clearTimeout(tt);tt=setTimeout(()=>{const Y=J("ml_explain",{});if(ta.value.trim())Y[key]=ta.value.slice(0,2000);else delete Y[key];SV("ml_explain",Y);cardEl.querySelector(".ix-saved").textContent="Saved on this device"},400)};
cardEl.querySelector(".ix-cmp").onclick=()=>{const v=ta.value.toLowerCase().replace(/-/g,""),out=cardEl.querySelector(".ix-cmpout");out.hidden=false;if(ta.value.trim().length<15){out.innerHTML="Write a sentence or two first, then compare.";return}
const kw=keywords(cd.recap.join(" "));const has=kw.filter(w=>v.includes(w.replace(/-/g,"").slice(0,6)));const miss=kw.filter(w=>!has.includes(w));
out.innerHTML=`<p>You used <b>${has.length} of ${kw.length}</b> key words from the recap${has.length?": "+has.map(w=>`<span class="ix-kw ok">✓ ${E(w)}</span>`).join(" "):""}.</p>${miss.length?`<p>Not yet in your words: ${miss.map(w=>`<span class="ix-kw">${E(w)}</span>`).join(" ")}</p>`:""}<p><b>The recap:</b></p><ul>${cd.recap.map(r=>`<li>${r}</li>`).join("")}</ul><small>💡 A rough word check, not a grade. Different words can be just as right.</small>`;if(has.length)complete("ix-ex-"+key,5,"✍️ Explained it back! +5 XP")}}
